raw = state.get('entities') or state.get('filtered_entities') or []
if isinstance(raw, str):
    import json
    try:
        raw = json.loads(raw)
    except Exception:
        raw = []
by_id = {}
for e in raw:
    if not isinstance(e, dict):
        continue
    txt = str(e.get('text') or '').strip()
    eid = str(e.get('id') or '').strip() or txt
    lbl = str(e.get('label') or '').strip()
    if not txt or not lbl:
        continue
    key = (lbl, eid)
    if key not in by_id or len(txt) > len(by_id[key]['text']):
        by_id[key] = {'text': txt, 'id': eid, 'label': lbl}
__result__ = list(by_id.values())
